import pyotp
import pytest

import app.auth as auth
from app.auth import AuthError, get_session, login, otp_header, verificar_otp
from app.config import USERS


def _otp(username: str) -> str:
    return pyotp.TOTP(USERS[username]["otp_secret"]).now()


def test_login_correcto_abre_sesion():
    s = login("alice", "alice-pass", _otp("alice"))
    assert s.username == "alice"
    assert get_session(s.token) == s


def test_login_password_incorrecto():
    with pytest.raises(AuthError):
        login("alice", "mal", _otp("alice"))
    with pytest.raises(AuthError):
        login("nadie", "alice-pass", _otp("alice"))


def test_login_otp_incorrecto_o_vacio():
    with pytest.raises(AuthError):
        login("alice", "alice-pass", "000000")
    with pytest.raises(AuthError):
        login("alice", "alice-pass", "")


def test_login_sin_otp_falla():
    with pytest.raises(TypeError):
        login("alice", "alice-pass")


def test_verificar_otp_acepta_paso_adyacente():
    secret = USERS["alice"]["otp_secret"]
    code = pyotp.TOTP(secret).at(pyotp.utils.strings_equal.__self__ if False else __import__("time").time() - 30)
    assert verificar_otp("alice", code)


def test_verificar_otp_rechaza_codigo_invalido():
    assert not verificar_otp("alice", "000000")
    assert not verificar_otp("alice", "")


def test_login_acepta_cualquier_codigo_si_verificar_otp_se_sustituye(monkeypatch):
    monkeypatch.setattr(auth, "verificar_otp", lambda username, code: True)
    s = login("bob", "bob-pass", "codigo-cualquiera")
    assert s.username == "bob"


def test_otp_header_es_dependencia_usable():
    assert otp_header() == ""
    assert otp_header("123456") == "123456"


def test_endpoint_login(client):
    r = client.post(
        "/login",
        json={"username": "bob", "password": "bob-pass", "otp": _otp("bob")},
    )
    assert r.status_code == 200
    assert client.post(
        "/login", json={"username": "bob", "password": "bob-pass", "otp": "000000"}
    ).status_code == 401
    assert client.post(
        "/login", json={"username": "bob", "password": "bob-pass"}
    ).status_code == 401
    assert client.post(
        "/login", json={"username": "bob", "password": "x", "otp": _otp("bob")}
    ).status_code == 401

